WITH matched AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions src LEFT JOIN promotions pr ON src.channel = pr.channel AND src.ends_on >= pr.starts_on AND src.ends_on <= DATE_ADD(pr.ends_on, 3)) SELECT id, channel, promo_code, starts_on, ends_on, promo_id, promotion_discount_pct FROM matched ORDER BY promotion_discount_pct NULLS FIRST, promo_id DESC;
